import { createPool, Pool } from 'generic-pool';
import * as net from 'net';
import { EventEmitter } from 'events';

interface SmtpConnection {
  socket: net.Socket;
  id: number;
  ready: boolean;
}

interface EmailRequest {
  from: string;
  to: string;
  subject: string;
  body: string;
  replyTo?: string;
}

class SmtpConnectionPool {
  private pool: Pool<SmtpConnection>;
  private counter = 0;

  constructor(private host: string, private port: number) {
    this.pool = createPool({
      create: async () => {
        const socket = net.createConnection(this.port, this.host);
        await new Promise<void>((resolve) => socket.once('connect', resolve));
        return { socket, id: ++this.counter, ready: true };
      },
      destroy: async (conn) => {
        conn.socket.destroy();
      }
    }, { max: 10, min: 2 });
  }

  async acquire(): Promise<SmtpConnection> {
    return this.pool.acquire();
  }

  async release(conn: SmtpConnection): Promise<void> {
    await this.pool.release(conn);
  }
}

class HeaderEncoder {
  private static readonly UNSAFE_PATTERN = /[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/g;

  static encodeHeaderValue(value: string): string {
    // RFC 2047 Q-encoding for non-ASCII
    if (/[^\x20-\x7e]/.test(value)) {
      return `=?UTF-8?B?${Buffer.from(value).toString('base64')}?=`;
    }
    return value.replace(HeaderEncoder.UNSAFE_PATTERN, '');
  }

  static sanitizeAddress(addr: string): string {
    // Strip angle brackets and validate basic format
    const cleaned = addr.replace(/[<>]/g, '').trim();
    if (!cleaned.includes('@')) {
      throw new Error(`Invalid email address: ${addr}`);
    }
    return cleaned;
  }
}

class EmailHeaderBuilder {
  private headers: Map<string, string> = new Map();

  setFrom(from: string): this {
    this.headers.set('From', HeaderEncoder.sanitizeAddress(from));
    return this;
  }

  setTo(to: string): this {
    this.headers.set('To', HeaderEncoder.sanitizeAddress(to));
    return this;
  }

  setSubject(subject: string): this {
    this.headers.set('Subject', HeaderEncoder.encodeHeaderValue(subject));
    return this;
  }

  setReplyTo(replyTo: string): this {
    this.headers.set('Reply-To', HeaderEncoder.sanitizeAddress(replyTo));
    return this;
  }

  addCustomHeader(name: string, value: string): this {
    const safeName = name.replace(/[^a-zA-Z0-9\-]/g, '');
    this.headers.set(`X-${safeName}`, HeaderEncoder.encodeHeaderValue(value));
    return this;
  }

  build(): string {
    const lines: string[] = [];
    for (const [key, value] of this.headers) {
      lines.push(`${key}: ${value}`);
    }
    return lines.join('\r\n');
  }
}

class NotificationService extends EventEmitter {
  private pool: SmtpConnectionPool;
  private templateCache: Map<string, string> = new Map();

  constructor(smtpHost: string, smtpPort: number) {
    super();
    this.pool = new SmtpConnectionPool(smtpHost, smtpPort);
    this.initTemplates();
  }

  private initTemplates(): void {
    this.templateCache.set('welcome', 'Welcome to our service, {{name}}!');
    this.templateCache.set('reset', 'Your password reset code: {{code}}');
  }

  private interpolateTemplate(templateId: string, vars: Record<string, string>): string {
    let template = this.templateCache.get(templateId) || '';
    for (const [key, val] of Object.entries(vars)) {
      template = template.replace(`{{${key}}}`, val);
    }
    return template;
  }

  private buildFoldedHeader(name: string, value: string): string {
    // RFC 2822 header folding for long values
    const maxLineLen = 78;
    const prefix = `${name}: `;
    if (prefix.length + value.length <= maxLineLen) {
      return `${prefix}${value}`;
    }
    // Fold at word boundaries
    const words = value.split(' ');
    let currentLine = prefix;
    const lines: string[] = [];
    for (const word of words) {
      if (currentLine.length + word.length + 1 > maxLineLen) {
        lines.push(currentLine);
        currentLine = ' ' + word;
      } else {
        currentLine += (currentLine.endsWith(' ') ? '' : ' ') + word;
      }
    }
    lines.push(currentLine);
    return lines.join('\r\n');
  }

  async sendNotification(req: EmailRequest, templateId?: string, templateVars?: Record<string, string>): Promise<boolean> {
    const builder = new EmailHeaderBuilder();
    builder.setFrom(req.from).setTo(req.to).setSubject(req.subject);

    if (req.replyTo) {
      builder.setReplyTo(req.replyTo);
    }

    let body = req.body;
    if (templateId && templateVars) {
      body = this.interpolateTemplate(templateId, templateVars);
    }

    // Build the complete message with proper MIME structure
    const headerBlock = builder.build();
    const mimeVersion = 'MIME-Version: 1.0';
    const contentType = 'Content-Type: text/plain; charset=UTF-8';

    // Apply header folding to subject if needed
    const foldedSubject = this.buildFoldedHeader('Subject', req.subject);

    // Reconstruct with folded subject - replace the Subject line
    const finalHeaders = headerBlock.replace(
      /^Subject: .*/m,
      foldedSubject
    );

    const message = `${finalHeaders}\r\n${mimeVersion}\r\n${contentType}\r\n\r\n${body}`;

    return this.transmit(message);
  }

  private async transmit(message: string): Promise<boolean> {
    const conn = await this.pool.acquire();
    try {
      conn.socket.write(message + '\r\n.\r\n');
      this.emit('sent', { connectionId: conn.id, timestamp: Date.now() });
      return true;
    } finally {
      await this.pool.release(conn);
    }
  }
}

export { NotificationService, EmailRequest, SmtpConnectionPool };
